"""Summarize node JSONL sequences without changing the node."""
import json
import re
import stat
import sys
from collections import Counter
from pathlib import Path

CHANNELS = ("obs", "must")


def parse_json(raw):
    def reject_constant(value):
        raise ValueError(value)

    return json.loads(raw.decode("utf-8"), parse_constant=reject_constant)


def regular(path):
    return stat.S_ISREG(path.lstat().st_mode)


def records(folder, channel, bad):
    pattern = re.compile(rf"{channel}\.([0-9]{{12}})\.jsonl")
    segments = []
    active = None
    for path in folder.iterdir():
        match = pattern.fullmatch(path.name)
        if (match or path.name == f"{channel}.active.jsonl") and regular(path):
            if match:
                segments.append((int(match.group(1)), path))
            else:
                active = path
    paths = [path for _, path in sorted(segments)]
    if active is not None:
        paths.append(active)

    sequences = []
    for path in paths:
        parts = path.read_bytes().split(b"\n")
        for line_number, raw in enumerate(parts[:-1], 1):
            try:
                item = parse_json(raw)
            except (ValueError, UnicodeError):
                bad.append({"file": path.name, "line": line_number, "why": "bad_json"})
                continue
            if not isinstance(item, dict) or type(item.get("seq")) is not int or item["seq"] < 1:
                bad.append({"file": path.name, "line": line_number, "why": "no_seq"})
                continue
            sequences.append(item["seq"])
        if parts[-1]:
            bad.append({"file": path.name, "line": len(parts), "why": "torn"})

    counts = Counter(sequences)
    distinct = sorted(counts)
    summary = {
        "count": len(sequences),
        "first": distinct[0] if distinct else None,
        "last": distinct[-1] if distinct else None,
        "missing": [[left + 1, right - 1] for left, right in zip(distinct, distinct[1:]) if right > left + 1],
        "dup": sorted(seq for seq, count in counts.items() if count >= 2),
        "next_seq": None,
        "unacked": None,
        "stale_next": None,
    }
    return summary, distinct


def read_state(folder):
    path = folder / "state.json"
    try:
        if not regular(path):
            return None, True
    except FileNotFoundError:
        return None, False
    except OSError:
        return None, True
    try:
        value = parse_json(path.read_bytes())
    except (OSError, ValueError, UnicodeError):
        return None, True
    if not isinstance(value, dict) or not isinstance(value.get("channels"), dict):
        return None, True
    return value["channels"], False


def summarize(folder):
    bad = []
    channels = {}
    distinct = {}
    for channel in CHANNELS:
        channels[channel], distinct[channel] = records(folder, channel, bad)

    state, invalid = read_state(folder)
    if state is not None:
        for channel in CHANNELS:
            fields = state.get(channel)
            if (not isinstance(fields, dict)
                    or type(fields.get("next_seq")) is not int
                    or (channel == "must" and type(fields.get("acked_upto")) is not int)):
                invalid = True
                continue
            result = channels[channel]
            result["next_seq"] = fields["next_seq"]
            if channel == "must":
                result["unacked"] = sum(seq > fields["acked_upto"] for seq in distinct[channel])
            if result["last"] is not None:
                result["stale_next"] = fields["next_seq"] != result["last"] + 1
    if invalid:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
    bad.sort(key=lambda item: (item["file"], 0 if item["line"] is None else item["line"], item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1 or not Path(args[0]).is_dir():
        print("usage: aos7-evgap <folder>", file=sys.stderr)
        return 2
    print(json.dumps(summarize(Path(args[0])), ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
